mapper.select:
SELECT id, title, type, file_key, is_downloadable, status, course_id, created_at, updated_at
FROM materials
WHERE id = #{id}

SELECT id, title, type, file_key, is_downloadable, status, course_id, created_at, updated_at
FROM materials
WHERE id = #{id}
  AND course_id = #{courseId}

SELECT id, title, type, file_key, is_downloadable, status, course_id, created_at, updated_at
FROM materials
WHERE file_key = #{fileKey}

SELECT id, title, type, file_key, is_downloadable, status, course_id, created_at, updated_at
FROM materials
WHERE course_id = #{courseId}

SELECT m.id, m.title, m.type, m.file_key, m.is_downloadable, m.status, m.course_id, m.created_at, m.updated_at
FROM materials m
INNER JOIN chapter_materials cm ON m.id = cm.material_id
WHERE cm.chapter_number = #{chapterNumber}
  AND cm.course_id = #{courseId}
